import math

def pi(n):
    count = 0
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(math.sqrt(i)) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

pi_34 = pi(34)
pi_35 = pi(35)

print(f"pi(34) = {pi_34}")
print(f"pi(35) = {pi_35}")
